@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700;800&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{--gold:#d7b87d;--gold-bright:#f0d7a1;--ink:#131b1a;--cream:#eee8d7;--muted:#a8aa9e;--red:#cf5a43;--panel:rgba(13,22,22,.86)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#1e332b;color:var(--cream);font-family:'DM Sans',sans-serif;user-select:none;-webkit-user-select:none;touch-action:none}#game{position:relative;width:100%;height:100%;overflow:hidden;background:#314638}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,15,16,.68) 0%,transparent 18%,transparent 70%,rgba(8,14,13,.50) 100%),radial-gradient(ellipse at center,transparent 47%,rgba(6,13,13,.32) 100%)}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:76px;padding:0 34px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(235,219,179,.12);background:linear-gradient(180deg,rgba(10,18,19,.86),rgba(10,18,19,.3));}.brand{display:flex;align-items:center;gap:12px}.brand-mark{font-size:27px;color:var(--gold);line-height:1}.brand-name{font-family:Cinzel,serif;font-size:15px;letter-spacing:2px;font-weight:600}.brand-name i{font-style:normal;color:var(--gold);font-size:10px}.brand-sub{font-size:8px;letter-spacing:2.4px;color:#b8b8a8;margin-top:3px}.region{display:flex;align-items:center;gap:9px;color:#d9d4c3;font-size:9px;letter-spacing:1.9px}.region-dot,.live-dot{height:6px;width:6px;border-radius:50%;background:#cbb175;box-shadow:0 0 9px #dbc38c}.weather{margin-left:17px;padding-left:17px;border-left:1px solid #ffffff35;color:#a7aa9f;font-size:8px}.icon-btn{background:rgba(230,216,179,.09);border:1px solid #dbbf803d;color:#ddc992;font:500 17px 'DM Sans';height:36px;padding:0 12px;cursor:pointer}.icon-btn span{font-size:9px;letter-spacing:1.5px;margin-left:4px}.mission-card{position:absolute;z-index:2;top:112px;left:38px;width:290px;padding:20px 21px 16px;background:linear-gradient(110deg,rgba(12,21,21,.89),rgba(12,21,21,.64));border-left:2px solid #c9aa6c;box-shadow:0 8px 35px #06120f55;backdrop-filter:blur(7px);transition:opacity .25s,transform .25s}.eyebrow{display:flex;align-items:center;gap:7px;font-size:8px;letter-spacing:1.8px;color:#cbb981}.eyebrow .line{height:1px;background:#d0b7795e;flex:1}.live-dot{width:5px;height:5px}.mission-card h1{font:500 25px/1.26 Cinzel,serif;letter-spacing:.7px;margin:17px 0 9px;color:#f1ead8}.mission-card h1 em,.pause-card h2 em{font-weight:400;font-style:normal;color:#d9bc80}.mission-card p{color:#b4b6a9;font-size:11px;line-height:1.7;margin:0 0 17px}.progress-label{display:flex;justify-content:space-between;color:#c7c5b6;font-size:8px;letter-spacing:1.2px;margin-bottom:7px}.progress-label b{color:#e2c783;font-weight:500}.progress-track,.health-track{height:3px;background:#ddd5bc32;overflow:hidden}.progress-track i,.health-track i{height:100%;width:0;display:block;background:linear-gradient(90deg,#9d804f,#e4cb91);transition:width .5s}.objective-list{padding-top:8px}.objective{height:22px;display:flex;gap:9px;align-items:center;color:#979c90;font-size:9px;letter-spacing:.4px}.objective .seal{font-size:12px;color:#c1a568;width:12px}.objective.done{color:#d6c48f}.objective.done .seal{color:#ecd591}.map-panel{position:absolute;top:94px;right:28px;width:230px;padding:12px 12px 9px;background:rgba(11,20,20,.75);border:1px solid #e6d5aa30;backdrop-filter:blur(5px);z-index:2;transition:opacity .25s,transform .25s}.map-title{font:500 9px Cinzel,serif;letter-spacing:1.4px;color:#d5c694;display:flex;justify-content:space-between;margin:1px 2px 7px}.map-title span{font:8px 'DM Sans';color:#999e91;letter-spacing:1px}.map-panel canvas{width:100%;height:auto;display:block;border:1px solid #e1d4ae22}.map-legend{display:flex;justify-content:space-between;font-size:7px;letter-spacing:1px;color:#a8aa9c;padding:7px 1px 1px}.status-row{position:absolute;bottom:48px;left:38px;display:flex;gap:28px;align-items:center;z-index:2}.health,.sync{display:flex;align-items:center;gap:9px}.health-icon{font-size:17px;color:#cf735c;text-shadow:0 0 9px #ce574655}.tiny-label{font-size:7px;letter-spacing:1.4px;color:#c6c2af;margin-bottom:5px}.health-track{width:102px;height:4px}.health-track i{width:100%;background:#c86b56}.sync>span{font-size:18px;color:#ddc586}.sync b{font-size:10px;font-weight:500;letter-spacing:.7px;color:#e5d5a5}.controls-hint{position:absolute;z-index:2;bottom:19px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#c3c0b2;font-size:8px;letter-spacing:1.1px;text-shadow:0 2px 5px #000}.controls-hint span{color:#f0d59a;border:1px solid #e3c77a65;border-radius:2px;padding:3px 5px;margin:0 3px;font-size:7px}.controls-hint i{font-style:normal;color:#ddc982;margin:0 6px}.toast{position:absolute;z-index:5;top:94px;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.3s;background:#101b1aeb;border:1px solid #d5bd7c66;color:#eddaa5;padding:11px 20px;font:10px Cinzel,serif;letter-spacing:1.6px;pointer-events:none}.toast.show{transform:translate(-50%,0);opacity:1}.interaction{position:absolute;z-index:3;left:50%;bottom:105px;transform:translateX(-50%);display:flex;align-items:center;gap:9px;color:#eee0bc;font-size:9px;letter-spacing:1.3px;opacity:0;transition:opacity .18s;pointer-events:none;text-shadow:0 2px 5px #000}.interaction.visible{opacity:1}.keycap{background:#e2d0a6;color:#17201d;padding:5px 8px;font-size:10px;font-weight:700;border-radius:2px}.stealth-state{position:absolute;z-index:2;right:28px;bottom:47px;font-size:8px;letter-spacing:1.5px;color:#c8d6a5;background:#0c1e19a8;padding:8px 12px;border-left:2px solid #93b375;opacity:0;transition:opacity .3s}.stealth-state.visible{opacity:1}.location-label{position:absolute;z-index:2;top:89px;left:50%;transform:translate(-50%,-8px);font:10px Cinzel,serif;letter-spacing:2.4px;color:#eadbb5;text-shadow:0 1px 6px #000;opacity:0;transition:opacity .6s,transform .6s;pointer-events:none}.location-label.show{opacity:1;transform:translate