px}.intro-edition{position:absolute;right:31px;bottom:24px;font:9px Cinzel,serif;letter-spacing:2px;color:#e0d5b17c}.pause-screen,.game-over{background:rgba(8,15,15,.71);backdrop-filter:blur(4px)}.hidden{opacity:0;visibility:hidden;pointer-events:none}.pause-card{text-align:center;width:min(420px,90vw);padding:40px 30px;background:rgba(14,24,23,.9);border:1px solid #d4bb7960;box-shadow:0 20px 80px #0007}.pause-card .eyebrow{justify-content:center}.pause-card h2{font:500 38px Cinzel,serif;letter-spacing:3px;margin:22px 0 9px}.pause-card p{color:#b4b8aa;font-size:12px}.pause-card .start-button{margin-top:23px}.reset-button{display:block;margin:18px auto 0;border:0;background:none;color:#b3ae9b;text-decoration:underline;text-underline-offset:4px;font-size:9px;letter-spacing:1px;cursor:pointer}.center-message{position:absolute;z-index:5;left:50%;top:43%;transform:translate(-50%,-50%);font:500 24px Cinzel,serif;letter-spacing:2px;text-shadow:0 2px 12px #000;opacity:0;transition:opacity .5s;pointer-events:none;text-align:center}.center-message.show{opacity:1}.mobile-controls{display:none}
@media(max-width:700px){.topbar{height:58px;padding:0 15px}.brand-mark{font-size:22px}.brand-name{font-size:12px;letter-spacing:1.4px}.brand-sub{font-size:7px;letter-spacing:1.5px}.region{font-size:7px;letter-spacing:1px}.weather{display:none}.mission-card{top:73px;left:12px;width:204px;padding:12px 13px 10px}.mission-card h1{font-size:18px;margin:11px 0 6px}.mission-card p{font-size:9px;line-height:1.5;margin-bottom:10px}.eyebrow{font-size:7px;letter-spacing:1px}.objective{height:18px;font-size:8px}.map-panel{top:69px;right:10px;width:148px;padding:7px}.map-title{font-size:7px;margin-bottom:4px}.map-title span{font-size:6px}.map-legend{font-size:6px;padding-top:4px}.status-row{left:15px;bottom:102px;gap:17px}.health-icon,.sync>span{font-size:15px}.tiny-label{font-size:6px}.health-track{width:72px}.controls-hint{display:none}.mobile-controls{display:block;position:absolute;z-index:4;inset:0;pointer-events:none}.joystick{position:absolute;bottom:27px;left:22px;width:122px;height:122px;pointer-events:auto;touch-action:none}.joy-ring{position:absolute;inset:0;border:1px solid #dfd1a569;border-radius:50%;background:#101b1a57;box-shadow:inset 0 0 25px #0005}.joy-knob{position:absolute;left:38px;top:38px;width:46px;height:46px;border-radius:50%;border:1px solid #f2dca6a8;background:radial-gradient(circle at 35% 30%,#e0ca9780,#89754b80);box-shadow:0 2px 9px #0007;transform:translate(0,0)}.action-buttons{position:absolute;right:14px;bottom:25px;width:180px;height:150px;pointer-events:none}.action-btn{position:absolute;pointer-events:auto;touch-action:none;width:52px;height:52px;border-radius:50%;border:1px solid #e7d09c98;color:#ebd5a0;background:rgba(16,28,25,.75);box-shadow:0 2px 9px #0005;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:1px}.action-btn span{font-size:20px;line-height:21px}.action-btn small{font-size:6px;letter-spacing:1px}.strike-btn{right:1px;bottom:39px;width:62px;height:62px;background:#6c302aa6;border-color:#e48c718c}.strike-btn span{font-size:22px}.interact-btn{right:68px;bottom:0;width:43px;height:43px}.interact-btn span{font-size:17px}.dash-btn{right:0;bottom:111px;width:45px;height:45px}.dash-btn span{font-size:18px}.stealth-btn{right:71px;bottom:91px;width:43px;height:43px}.stealth-btn span{font-size:17px}.pause-btn{right:13px;bottom:auto;top:68px;width:26px;height:24px}.sound-credit{display:none}.interaction{bottom:171px;font-size:8px}.stealth-state{bottom:105px;right:12px;font-size:6px;padding:6px 8px}.location-label{top:63px;font-size:8px}.intro-content{margin-left:0;margin-top:-3vh}.intro-kicker{font-size:7px;letter-spacing:1.7px}.intro-title{font-size:58px;margin:24px 0 17px}.intro-content p{font-size:10px}.intro-foot{font-size:6px;line-height:1.8;max-width:270px}.intro-edition{font-size:7px;right:14px;bottom:13px}.center-message{font-size:18px}.weather{display:none}}
@media(max-height:560px) and (min-width:701px){.mission-card{top:86px;padding:12px 16px}.mission-card h1{font-size:21px;margin:10px 0 5px}.mission-card p{margin-bottom:10px}.objective{height:18px}.map-panel{top:82px}.status-row{bottom:34px}.controls-hint{bottom:12px}.intro-title{margin:18px 0;font-size:68px}.intro-divider{margin:16px 0}}

(() => {
'use strict';
const canvas = document.getElementById('world');
const ctx = canvas.getContext('2d', { alpha: false });
const mapCanvas = document.getElementById('minimap');
const mapCtx = mapCanvas.getContext('2d');
const $ = id => document.getElementById(id);
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const TAU = Math.PI * 2;
let W = 0, H = 0, dpr = 1, last = 0, elapsed = 0, running = false, started = false, paused = false;
let toastTimer = 0, attackTimer = 0, hitFlash = 0, win = false, locationTimer = 0, saveTimer = 0;
const WORLD = { w: 3600, h: 3600 };
const input = { x: 0, y: 0, sprint: false, keys: new Set(), joy: false, joyX: 0, joyY: 0 };
const player = { x: 1800, y: 1840, vx: 0, vy: 0, angle: -Math.PI / 2, health: 100, stealth: false, attack: 0, step: 0, invuln: 0, seals: 0, found: 0, explored: new Set(), kills: 0 };
const objectiveSpots = [
  { x: 690, y: 660, name: 'THE OLD WATCHTOWER', glyph: '✳', taken: false },
  { x: 2940, y: 930, name: 'CROWFEATHER CAMP', glyph: '✳', taken: false },
  { x: 2480, y: 2980, name: 'THE FORGOTTEN SHRINE', glyph: '✳', taken: false }
];
const landmarks = [
  { x: 1800, y: 1840, name: 'PINEWATCH CROSSING' }, { x: 680, y: 700, name: 'THE OLD WATCHTOWER' },
  { x: 2940, y: 940, name: 'CROWFEATHER CAMP' }, { x: 2470, y: 2980, name: 'THE FORGOTTEN SHRINE' },
  { x: 580, y: 2550, name: 'WILLOWMERE' }, { x: 1800, y: 550, name: 'EAGLE’S REST' },
  { x: 3300, y: 2190, name: 'THE NORTH TRAIL' }, { x: 1590, y: 3170, name: 'ASHEN GROVE' }
];
const hash = (x, y, seed = 0) => { let n = (Math.imul(x | 0, 374761393) + Math.imul(y | 0, 668265263) + Math.imul(seed | 0, 1442695041)) | 0; n = Math.imul(n ^ (n >>> 13), 1274126177); return ((n ^ (n >>> 16)) >>> 0) / 4294967295; };
const distance = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
function resize() { dpr = Math.min(window.devicePixelRatio || 1, 1.7); W = innerWidth; H = innerHeight; canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr); canvas.style.width = `${W}px`; canvas.style.height = `${H}px`; ctx.setTransform(dpr, 0, 0, dpr, 0, 0); }
window.addEventListener('resize', resize); resize();
function loadSave() {
  try { const s = JSON.parse(localStorage.getItem('ashes-frontier-save') || 'null'); if (!s || s.v !== 1) return; player.x = clamp(s.x ?? player.x, 100, WORLD.w - 100); player.y = clamp(s.y ?? player.y, 100, WORLD.h - 100); player.health = clamp(s.health ?? 100, 1, 100); player.kills = s.kills ?? 0; objectiveSpots.forEach((o, i) => { o.taken = !!s.seals?.[i]; }); player.seals = objectiveSpots.filter(o => o.taken).length; player.explored = new Set(s.explored || []); }
  catch (_) { /* A fresh offline save will be created on the next checkpoint. */ }
  updateObjectives();
}
function save() { try { localStorage.setItem('ashes-frontier-save', JSON.stringify({ v: 1, x: player.x, y: player.y, health: player.health, kills: player.kills, seals: objectiveSpots.map(o => o.taken), explored: [...player.explored] })); } catch (_) {} }
function updateObjectives() { $('progressText').textContent = `${player.seals} / 3`; $('progressBar').style.width = `${player.seals / 3 * 100}%`; $('syncText').textContent = `${Math.round(player.explored.size / landmarks.length * 100)}%`; $('objectiveList').innerHTML = objectiveSpots.map((o, i) => `<div class="objective ${o.taken ? 'done' : ''}"><span class="seal">${o.taken ? '✓' : '◆'}</span>${['THE WATCHTOWER SEAL', 'CAMP SEAL', 'SHRINE SEAL'][i]}</div>`).join(''); }
function announce(text, duration = 2500) { const el = $('toast'); el.textContent = text; el.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('show'), duration); }
function centerMessage(text, time = 1600) { const el = $('centerMessage'); el.innerHTML = text; el.classList.add('show'); setTimeout(() => el.classList.remove('show'), time); }
function discoverLocation() { let nearest = null, dmin = 180; for (const l of landmarks) { const d = distance(player, l); if (d < dmin && !player.explored.has(l.name)) { nearest = l; dmin = d; } } if (nearest) { player.explored.add(nearest.name); $('locationLabel').textContent = nearest.name; $('locationLabel').classList.add('show'); setTimeout(() => $('locationLabel').classList.remove('show'), 2600); updateObjectives(); save(); } }
loadSave();

function pathNoise(x, y, seed) { return hash(Math.floor(x / 120), Math.floor(y / 120), seed); }
function drawGround(camX, camY) {
  const tile = 80, sx = Math.floor(camX / tile) * tile, sy = Math.floor(camY / tile) * tile;
  for (let y = sy; y < camY + H + tile; y += tile) for (let x = sx; x < camX + W + tile; x += tile) {
    const n = hash(x / tile, y / tile, 3); const meadow = Math.sin(x * .001 + y * .0007) * .5 + .5;
    const r = 43 + n * 16 + meadow * 5, g = 69 + n * 22 + meadow * 6, b = 47 + n * 13;
    ctx.fillStyle = `rgb(${r|0},${g|0},${b|0})`; ctx.fillRect(x - camX, y - camY, tile + 1, tile + 1);
    if (n > .77) { ctx.fillStyle = `rgba(185,174,116,${.04 + n * .035})`; ctx.beginPath(); ctx.ellipse(x - camX + n * tile, y - camY + 12, 14, 5, n, 0, TAU); ctx.fill(); }
  }
  // Meandering creek with softly layered banks.
  const waterX = 1620 - camX, off = -camY;
  for (let layer = 0; layer < 4; layer++) {
    ctx.beginPath(); for (let yy = -120; yy <= H + 120; yy += 16) { const wx = waterX + Math.sin((yy + off) * .0011 + .6) * 112 + Math.sin((yy + off) * .0032) * 27; const x = wx + (layer - 1.5) * (31 + layer * 3); if (yy === -120) ctx.moveTo(x, yy); else ctx.lineTo(x, yy); }
    ctx.lineWidth = layer === 0 || layer === 3 ? 9 : 18; ctx.strokeStyle = ['rgba(110,125,83,.26)','rgba(91,119,84,.58)','rgba(68,105,88,.75)','rgba(114,122,81,.34)'][layer]; ctx.stroke();
  }
  ctx.beginPath(); for (let yy = -120; yy <= H + 120; yy += 12) { const wx = waterX + Math.sin((yy + off) * .0011 + .6) * 112 + Math.sin((yy + off) * .0032) * 27; if (yy === -120) ctx.moveTo(wx, yy); else ctx.lineTo(wx, yy); }
  ctx.lineWidth = 28; ctx.strokeStyle = '#436b68'; ctx.stroke(); ctx.lineWidth = 17; ctx.strokeStyle = '#56807a'; ctx.stroke();
  ctx.beginPath(); for (let yy = -120; yy <= H + 120; yy += 12) { const wx = waterX + Math.sin((yy + off) * .0011 + .6) * 112 + Math.sin((yy + off) * .0032) * 27 - 4; if (yy === -120) ctx.moveTo(wx, yy); else ctx.lineTo(wx, yy); } ctx.lineWidth = 2; ctx.strokeStyle = 'rgba(184,197,158,.38)'; ctx.stroke();
  // Pale wheel-rutted trails connect the frontier settlements.
  ctx.lineCap = 'round';
  for (let p = 0; p < 3; p++) { const a = landmarks[(p * 2) % landmarks.length], b = landmarks[(p * 2 + 3) % landmarks.length]; ctx.beginPath(); ctx.moveTo(a.x - camX, a.y - camY); const mx = (a.x + b.x) / 2 + (pathNoise(a.x, b.y, p) - .5) * 150, my = (a.y + b.y) / 2 + (pathNoise(b.x, a.y, p + 1) - .5) * 180; ctx.quadraticCurveTo(mx - camX, my - camY, b.x - camX, b.y - camY); ctx.lineWidth = 15; ctx.strokeStyle = 'rgba(174,157,113,.14)'; ctx.stroke(); ctx.setLineDash([6, 9]); ctx.lineWidth = 1.5; ctx.strokeStyle = 'rgba(212,197,146,.22)'; ctx.stroke(); ctx.setLineDash([]); }
}
function drawPine(x, y, size, seed, camX, camY) {
  const px = x - camX, py = y - camY, s = size, sway = Math.sin(elapsed * .45 + seed) * .8;
  // Shadow
  ctx.fillStyle = 'rgba(9,18,15,.35)'; ctx.beginPath(); ctx.ellipse(px + s * .14, py + s * .35, s * .6, s * .25, -.3, 0, TAU); ctx.fill();
  ctx.fillStyle = '#493f2c'; ctx.fillRect(px - s * .10, py - s * .15, s * .2, s * .6);
  for (let k = 0; k < 3; k++) { const yy = py - s * (.48 - k * .22), width = s * (.63 - k * .08); ctx.beginPath(); ctx.moveTo(px + sway * (k + 1) * .2, yy - s * .46); ctx.lineTo(px + width, yy + s * .25); ctx.lineTo(px - width, yy + s * .25); ctx.closePath(); ctx.fillStyle = ['#263e32','#2d4938','#38533b'][k]; ctx.fill(); ctx.beginPath(); ctx.moveTo(px, yy - s * .39); ctx.lineTo(px + width * .73, yy + s * .20); ctx.lineTo(px - width * .62, yy + s * .20); ctx.closePath(); ctx.fillStyle = ['#314a36','#3a573b','#4a6342'][k]; ctx.globalAlpha = .8; ctx.fill(); ctx.globalAlpha = 1; }
  if (s > 28) { ctx.beginPath(); ctx.arc(px - s * .22, py - s * .29, s * .14, 0, TAU); ctx.fillStyle = '#b7b76c32'; ctx.fill(); }
